    html += cell('🍑', '羞耻', bar(lil['羞耻值'], '#f09ec0'));
    html += cell('🎭', '暴露', bar(lil['秘密暴露度'], '#9a7ff0'));
    html += cell('👗', '衣着', esc(lil['当前衣着']));
    document.getElementById('main').innerHTML = html;

    var tasks = st['任务'] || {}, names = Object.keys(tasks);
    var taskEl = document.getElementById('task');
    if (names.length) {
      var t = tasks[names[0]];
      taskEl.style.display = '';
      taskEl.innerHTML = '🗡️ <b>' + esc(names[0]) + '</b>　委托方：' + esc(t['委托方']) +
        '　目标：' + esc(t['目标']) + '　地点：' + esc(t['地点']) + '　难度：' + esc(t['难度']) +
